/* Sequential chunks equal full styles; native snapshots survive reload/GC/context destruction. */
#include "flashvm/swf_sound.h"
#include "flashvm/gc.h"
#include "swf_sound_fixture.hpp"
using namespace sound_fixture;
struct Sink { fvm_detail::vector<short> pcm; };
static FVM_Result write(void *p,const FVM_MediaFrame *f){Sink *s=(Sink*)p;s->pcm.resize(f->size/2);std::memcpy(s->pcm.begin(),f->data,f->size);return FVM_OK;}
static FVM_Result stop(void*){return FVM_OK;}
static void compare(FVM_Context *c,unsigned channels){Sink sink;FVM_MediaOutput out={sizeof(out),&sink,write,stop};FVM_AudioChannel *channel=0;assert(fvm_audio_channel_create(c,&out,&channel)==FVM_OK && fvm_swf_sound_event_submit(c,0,channel)==FVM_OK && fvm_audio_channel_close(channel)==FVM_OK);const size_t chunks[]={1,2,3,17,256};for(unsigned part=0;part<5;++part){FVM_SWFSoundVoice *v=0;assert(fvm_swf_sound_voice_open(c,0,&v)==FVM_OK && v);FVM_SWFSoundVoiceInfo info;info.struct_size=sizeof(info);assert(fvm_swf_sound_voice_info(v,&info)==FVM_OK && info.channels==channels && info.play_count==3 && !info.finished);short pcm[512]={123};size_t n=99;assert(fvm_swf_sound_voice_read(v,1,pcm,channels-1,&n)==FVM_INVALID_ARGUMENT && !n && pcm[0]==123);assert(fvm_swf_sound_voice_info(v,&info)==FVM_OK && !info.play_index && !info.frame_in_play);size_t at=0;for(;;){FVM_Result r=fvm_swf_sound_voice_read(v,chunks[part],pcm,512,&n);if(r==FVM_NOT_FOUND){assert(!n);break;}assert(r==FVM_OK && n && n<=chunks[part]*channels && at+n<=sink.pcm.size());assert(!std::memcmp(pcm,sink.pcm.begin()+at,n*2));at+=n;}assert(at==sink.pcm.size());assert(fvm_swf_sound_voice_info(v,&info)==FVM_OK && info.finished && info.play_index==3 && !info.frame_in_play);assert(fvm_swf_sound_voice_read(v,0,0,0,&n)==FVM_OK && !n);assert(fvm_swf_sound_voice_close(v)==FVM_OK);}}
struct Bits { Bytes b;unsigned n;Bits():n(0){}void put(unsigned v,unsigned width){for(unsigned i=width;i;--i){if(!(n%8))b.push_back(0);b[b.size()-1]|=((v>>(i-1))&1)<<(7-n%8);++n;}} };
static Bytes file(unsigned flags,unsigned frames,const Bytes &data,unsigned version){Bytes defs;tag(defs,14,sound(7,flags,frames,data.begin(),data.size()));Bytes e;word(e,7);e.push_back(12);word(e,3);e.push_back(3);integer(e,0);word(e,32768);word(e,0);integer(e,2);word(e,0);word(e,32768);integer(e,7);word(e,32768);word(e,32768);tag(defs,15,e);return movie(defs,version);}
int main(){FVM_Config cfg;FVM_Runtime *rt=0;FVM_Context *c=0;assert(fvm_config_init(&cfg)==FVM_OK && fvm_runtime_create(&cfg,&rt)==FVM_OK && fvm_context_create(rt,&c)==FVM_OK);FVM_SWFSoundVoice *v=(FVM_SWFSoundVoice*)1;assert(fvm_swf_sound_voice_open(c,0,&v)==FVM_UNSUPPORTED && !v);for(unsigned version=1;version<=8;++version)for(unsigned ch=1;ch<=2;++ch){Bytes bytes;for(unsigned i=0;i<5*ch;++i)bytes.push_back((unsigned char)(i*61));Bytes swf=file(12|(ch-1),5,bytes,version);assert(fvm_load_memory(c,swf.begin(),swf.size())==FVM_OK);compare(c,ch);bytes.clear();const short values[]={-32768,-123,0,123,32767};for(unsigned i=0;i<5;++i)for(unsigned j=0;j<ch;++j){unsigned char raw[2];std::memcpy(raw,&values[i],2);if(version<4){bytes.push_back(raw[0]);bytes.push_back(raw[1]);}else word(bytes,(unsigned short)values[i]);}swf=file((version<4?0:0x30)|14|(ch-1),5,bytes,version);assert(fvm_load_memory(c,swf.begin(),swf.size())==FVM_OK);compare(c,ch);}
for(unsigned width=2;width<=5;++width)for(unsigned ch=1;ch<=2;++ch){Bits b;b.put(width-2,2);for(unsigned frame=0;frame<4098;++frame)for(unsigned channel=0;channel<ch;++channel){if(frame%4096==0){b.put(channel?33536:32000,16);b.put(63,6);}else b.put((frame*13+channel*7)%(1U<<width),width);}Bytes swf=file(0x1e|(ch-1),4098,b.b,8);assert(fvm_load_memory(c,swf.begin(),swf.size())==FVM_OK);compare(c,ch);}
Bytes bytes;bytes.push_back(0);bytes.push_back(128);bytes.push_back(255);Bytes swf=file(12,3,bytes,8);assert(fvm_load_memory(c,swf.begin(),swf.size())==FVM_OK && fvm_swf_sound_voice_open(c,0,&v)==FVM_OK);assert(fvm_gc_collect(c,0)==FVM_OK);Bytes empty,replacement=movie(empty);assert(fvm_load_memory(c,replacement.begin(),replacement.size())==FVM_OK);fvm_context_destroy(c);fvm_runtime_destroy(rt);short pcm[32];size_t n=0;assert(fvm_swf_sound_voice_read(v,32,pcm,32,&n)==FVM_OK && n==9 && pcm[0]==-16384);assert(fvm_swf_sound_voice_read(v,1,pcm,32,&n)==FVM_NOT_FOUND && !n);assert(fvm_swf_sound_voice_close(v)==FVM_OK && fvm_swf_sound_voice_close(0)==FVM_OK);return 0;}
